"""Weights text from train.py -> app/src/main/java/com/arco/stride/StepNetWeights.java. Usage: python3 -I export_java.py <weights.txt> <out.java>"""
import sys
m = {}
for line in open(sys.argv[1]):
    p = line.split(); m[p[0]] = p[1:]
h = len(m['gru.bias_hh_l0']) // 3; nin = len(m['gru.weight_ih_l0']) // (3 * h)
def arr(k):
    v = [x + 'f' for x in m[k]]
    return '{\n            ' + ',\n            '.join(', '.join(v[i:i + 8]) for i in range(0, len(v), 8)) + '}'
src = f"""package com.arco.stride;

/** Generated by tools/ml/export_java.py from tools/ml/stepnet.txt. Do not edit. */
final class StepNetWeights {{
    private StepNetWeights() {{}}
    static final int NIN = {nin}, H = {h};
    static final float[] WIH = {arr('gru.weight_ih_l0')};
    static final float[] WHH = {arr('gru.weight_hh_l0')};
    static final float[] BIH = {arr('gru.bias_ih_l0')};
    static final float[] BHH = {arr('gru.bias_hh_l0')};
    static final float[] WOUT = {arr('out.weight')};
    static final float BOUT = {m['out.bias'][0]}f;
}}
"""
open(sys.argv[2], 'w').write(src)
print('wrote', sys.argv[2], 'nin', nin, 'h', h)
